/*taskExecutionMapper.selectTaskExecutionList*/
SELECT A.EXECUTION_NO AS EXECUTION_NO /*수행번호*/ ,A.EXECUTION_NAME AS EXECUTION_NAME /*수행이름*/ ,A.EXECUTION_CONFIG AS EXECUTION_CONFIG /*수행설정*/ ,A.EXECUTION_POST_PROCESS AS EXECUTION_POST_PROCESS /*수행후처리정보*/ ,A.EXECUTION_START_TIME AS EXECUTION_START_TIME /*수행시작일시*/ ,CONCAT(DATE_FORMAT(LEFT(A.EXECUTION_START_TIME,14),'%Y.%m.%d %H:%i:%s'),' ',RIGHT(A.EXECUTION_START_TIME,3)) AS EXECUTION_START_TIME_FORMAT /*수행시작일시포멧*/ ,A.EXECUTION_END_TIME AS EXECUTION_END_TIME /*수행종료일시*/ ,CONCAT(DATE_FORMAT(LEFT(A.EXECUTION_END_TIME,14),'%Y.%m.%d %H:%i:%s'),' ',RIGHT(A.EXECUTION_END_TIME,3)) AS EXECUTION_END_TIME_FORMAT /*수행종료일시포멧*/ ,A.EXECUTION_SERVER AS EXECUTION_SERVER /*수행서버*/ ,A.EXECUTION_TIME AS EXECUTION_TIME /*수행시간*/ ,IFNULL(A.EXECUTION_TIME,ROUND(TIMESTAMPDIFF(MICROSECOND,STR_TO_DATE(A.EXECUTION_START_TIME,'%Y%m%d%H%i%s%f'),NOW(6))/1000,0)) AS EXECUTION_TIME_FLOW /*수행시간흐름*/ ,@executionLogSize:=IFNULL(B.EXECUTION_LOG_SIZE,0) AS EXECUTION_LOG_SIZE /*수행로그크기*/ ,IF(@executionLogSize=0,NULL,'*') AS EXECUTION_LOG /*수행로그*/ ,@exceptionLogSize:=IFNULL(B.EXCEPTION_LOG_SIZE,0) AS EXCEPTION_LOG_SIZE /*예외로그크기*/ ,IF(@exceptionLogSize=0,NULL,'*') AS EXCEPTION_LOG /*예외로그*/ ,A.EXCEPTION_TYPE AS EXCEPTION_TYPE /*예외구분*/ ,A.EXCEPTION_YN AS EXCEPTION_YN /*예외여부*/ ,UNIX_TIMESTAMP(SYS_CREATION_DATE)*1000 AS SYS_CREATION_DATE /*생성일*/ ,UNIX_TIMESTAMP(SYS_UPDATE_DATE)*1000 AS SYS_UPDATE_DATE /*수정일*/ FROM ( SELECT * FROM TB_TASK_EXECUTION_HISTORY
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND EXECUTION_NAME=#{executionName} AND EXCEPTION_YN=#{exceptionYn}
OR EXCEPTION_TYPE='error' OR EXCEPTION_TYPE='interrupt'
ORDER BY EXECUTION_NO DESC LIMIT #{rownum} ) A LEFT JOIN ( SELECT A.EXECUTION_NO,A.EXECUTION_LOG_SIZE,B.EXCEPTION_LOG_SIZE FROM ( SELECT EXECUTION_NO,IFNULL(SUM(LENGTH(LOG_DATA)),0) AS EXECUTION_LOG_SIZE FROM TB_TASK_EXECUTION_LOG WHERE LOG_TYPE='executionLog'
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND EXECUTION_NAME=#{executionName}
GROUP BY EXECUTION_NO,EXECUTION_NAME ) A LEFT JOIN( SELECT EXECUTION_NO,IFNULL(SUM(LENGTH(LOG_DATA)),0) AS EXCEPTION_LOG_SIZE FROM TB_TASK_EXECUTION_LOG WHERE LOG_TYPE='exceptionLog'
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND EXECUTION_NAME=#{executionName}
GROUP BY EXECUTION_NO,EXECUTION_NAME ) B ON A.EXECUTION_NO=B.EXECUTION_NO ) B ON A.EXECUTION_NO=B.EXECUTION_NO
SELECT * FROM TB_TASK_EXECUTION_HISTORY

mapper.update:

/*taskExecutionMapper.insertTaskExecutionInfo*/
INSERT INTO TB_TASK_EXECUTION_HISTORY (
	EXECUTION_NO /*수행번호*/
	,EXECUTION_NAME /*수행이름*/
	,EXECUTION_CONFIG /*수행설정*/
	,EXECUTION_START_TIME /*수행시작일시*/
	,EXECUTION_END_TIME /*수행종료일시*/
	,EXECUTION_SERVER /*수행서버*/			
	,EXECUTION_TIME /*수행시간*/
	,EXCEPTION_TYPE /*예외구분*/
	,EXCEPTION_YN /*예외여부*/
	,EXECUTION_POST_PROCESS /*후처리정보*/
	,SYS_CREATION_DATE /*생성일*/
) VALUES (
	CAST(#{executionNo,jdbcType=VARCHAR} AS UNSIGNED)
	,#{executionName,jdbcType=VARCHAR}
	,#{executionConfig,jdbcType=VARCHAR}
	,#{executionStartTime,jdbcType=VARCHAR}
	,#{executionEndTime,jdbcType=VARCHAR}
	,#{executionServer,jdbcType=VARCHAR}
	,#{executionTime,jdbcType=VARCHAR}
	,#{exceptionType,jdbcType=VARCHAR}
	,#{exceptionYn,jdbcType=VARCHAR}
	,#{executionPostProcess,jdbcType=VARCHAR}
	,NOW(3)
)

/*taskExecutionMapper.updateTaskExecutionInfo*/ UPDATE TB_TASK_EXECUTION_HISTORY
EXECUTION_NAME=#{executionName}/*수행이름*/, EXECUTION_CONFIG=#{executionConfig}/*수행설정*/, EXECUTION_START_TIME=#{executionStartTime}/*수행시작일시*/, EXECUTION_END_TIME=#{executionEndTime}/*수행종료일시*/, EXECUTION_SERVER=#{executionServer}/*수행서버*/, EXECUTION_TIME=#{executionTime}/*수행시간*/, EXECUTION_POST_PROCESS=#{executionPostProcess}/*후처리정보*/, EXCEPTION_TYPE=#{exceptionType}/*예외구분*/, EXCEPTION_YN=#{exceptionYn}/*예외여부*/, SYS_UPDATE_DATE=NOW(3),
WHERE EXECUTION_NO=#{executionNo}

mapper.select:
/*taskExecutionMapper.selectTaskLogList*/
SELECT EXECUTION_NO AS EXECUTION_NO ,EXECUTION_NAME AS EXECUTION_NAME ,LOG_SEQ AS LOG_SEQ ,LOG_TYPE AS LOG_TYPE ,LOG_DATA AS LOG_DATA FROM TB_TASK_EXECUTION_LOG
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND LOG_TYPE=#{logType} AND LOG_SEQ=#{logSeq}
SELECT B.EXECUTION_NO AS EXECUTION_NO ,B.EXECUTION_NAME AS EXECUTION_NAME ,B.LOG_SEQ AS LOG_SEQ ,B.LOG_TYPE AS LOG_TYPE ,SUBSTRING(B.LOG_DATA,A.EXTRACT_POSITION,A.EXTRACT_SIZE) AS LOG_DATA FROM ( SELECT
A.EXECUTION_NO ,A.LOG_SEQ ,A.LOG_START_POSITION ,A.LOG_DATA_SIZE ,A.LOG_END_POSITION ,@logChunkStartPosition:=#{logChunkStartPosition,jdbcType=NUMERIC} AS LOG_CHUNK_START_POSITION ,@logChunkSize:=#{logChunkSize,jdbcType=NUMERIC} AS LOG_CHUNK_SIZE ,@chunkEndPosition:=(@logChunkStartPosition+@logChunkSize-1) AS CHUNK_END_POSITION ,@extractYn:=IF(IF(A.LOG_START_POSITION<=@chunkEndPosition,1,0)+IF(A.LOG_END_POSITION>=@logChunkStartPosition,1,0)<2,'N','Y') AS EXTRACT_YN ,@extractPosition:=CASE WHEN @extractYn='Y' AND A.LOG_START_POSITION<=@logChunkStartPosition AND A.LOG_END_POSITION>=@logChunkStartPosition THEN (@logChunkStartPosition-A.LOG_START_POSITION)+1 WHEN @extractYn='Y' AND A.LOG_START_POSITION<=@chunkEndPosition AND A.LOG_END_POSITION>=@chunkEndPosition THEN 1 WHEN @extractYn='Y' THEN 1 ELSE NULL END AS EXTRACT_POSITION ,@extractSize:=CASE WHEN @extractYn='Y' AND A.LOG_START_POSITION<=@logChunkStartPosition AND A.LOG_END_POSITION>=@logChunkStartPosition THEN IF(A.LOG_DATA_SIZE<@logChunkSize,A.LOG_DATA_SIZE-@extractPosition,@logChunkSize) WHEN @extractYn='Y' AND A.LOG_START_POSITION<=@chunkEndPosition AND A.LOG_END_POSITION>=@chunkEndPosition THEN (@chunkEndPosition-A.LOG_START_POSITION)+1 WHEN @extractYn='Y' THEN A.LOG_DATA_SIZE ELSE NULL END AS EXTRACT_SIZE
FROM ( SELECT EXECUTION_NO AS EXECUTION_NO ,IF(LOG_SEQ=1,(@logSum:=0)+1,LOG_SEQ) AS LOG_SEQ ,IF(@logSum=0,1,@logSum+1) AS LOG_START_POSITION ,@executionLogSize:=LENGTH(LOG_DATA) AS LOG_DATA_SIZE ,@logSum:=(@logSum+@executionLogSize) AS LOG_END_POSITION FROM TB_TASK_EXECUTION_LOG
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND LOG_TYPE=#{logType}
) A ) A ,( SELECT EXECUTION_NO AS EXECUTION_NO ,EXECUTION_NAME AS EXECUTION_NAME ,LOG_SEQ AS LOG_SEQ ,LOG_TYPE AS LOG_TYPE ,LOG_DATA AS LOG_DATA FROM TB_TASK_EXECUTION_LOG
AND 1!=1 AND EXECUTION_NO=#{executionNo} AND LOG_TYPE=#{logType}
) B WHERE 1=1 AND A.EXTRACT_YN='Y' AND A.EXECUTION_NO=B.EXECUTION_NO AND A.LOG_SEQ=B.LOG_SEQ

mapper.update:

/*taskExecutionMapper.insertTaskExecutionLogInfo*/
INSERT INTO TB_TASK_EXECUTION_LOG (
	EXECUTION_NO /*TASK번호*/
	,EXECUTION_NAME /*수행이름*/
	,LOG_TYPE /*log구분*/
	,LOG_SEQ /*log순차*/
	,LOG_DATA /*log데이타*/	
	,SYS_CREATION_DATE /*생성일*/
) VALUES (
	#{executionNo,jdbcType=VARCHAR}
	,#{executionName,jdbcType=VARCHAR}
	,#{logType,jdbcType=VARCHAR}
	,(SELECT IFNULL(MAX(A.LOG_SEQ),0)+1 FROM (SELECT EXECUTION_NO,LOG_SEQ FROM TB_TASK_EXECUTION_LOG WHERE EXECUTION_NO=#{executionNo,jdbcType=NUMERIC} AND LOG_TYPE=#{logType,jdbcType=VARCHAR}) A)
	,#{logData,jdbcType=BLOB}
	,NOW(3)
)
